 let permit=authority::signed_record(&json!({"schema_version":"lab-completion-recovery-authorization/v1","authorization_id":"reviewer-fresh-recovery","operation_id":"operation-1","operation_fingerprint":authority::operation_fingerprint(&intent.core).unwrap(),"scope":intent.scope,"allowed_verb":"reconcile_operation","message_core_sha256":roots::hash(&wire::signing_bytes(&wire::authorization_core(&request).unwrap()).unwrap()),"subject_binding":subject,"not_before":now-1,"expires_at":now+120,"observed_phase":"UNKNOWN","action":action,"preimages":[subject],"next_sequence":1,"next_offset":0,"cumulative_bytes":0,"cumulative_actions":1,"original_deadline":intent.core["operation_expires_at"]}),"fixture-issuer",&intent.key).unwrap();request["authorization_binding"]=wire::content_digest(&encode(&permit).unwrap());encode(&json!({"schema_version":"lab-completion-broker-frame/v1","request":request,"permit":permit})).unwrap()
